package com.courtstory.app;
import org.junit.Test;import static org.junit.Assert.*;import org.json.JSONObject;import java.time.*;import static com.courtstory.app.Domain.*;
public class ReleaseRulesTest {
 @Test public void seasonHasExclusiveEnd(){assertEquals(LocalDate.of(2026,1,1).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli(),ReportPeriod.start(-2026));assertEquals(LocalDate.of(2027,1,1).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli(),ReportPeriod.end(-2026));assertEquals("Season 2026",ReportPeriod.label(-2026));assertEquals(Long.MAX_VALUE,ReportPeriod.end(0));}
 @Test public void remindersRejectInvalidLimits(){JSONObject s=obj();assertNull(SettingsRules.validate(s));put(s,"reminderLeadMinutes",-1);assertNotNull(SettingsRules.validate(s));put(s,"reminderLeadMinutes",0);put(s,"postSessionDelayMinutes",0);assertNotNull(SettingsRules.validate(s));put(s,"postSessionDelayMinutes",10080);assertNull(SettingsRules.validate(s));put(s,"defaultSeason",1999);assertNotNull(SettingsRules.validate(s));put(s,"defaultSeason",2100);assertNull(SettingsRules.validate(s));}
 @Test public void revisionAdvancesEvenWhenEditorCopyIsOld(){JSONObject lib=newLibrary(),r=obj();put(r,"id",id());put(r,"revision",0);upsert(lib,"players",copy(r));upsert(lib,"players",copy(r));upsert(lib,"players",copy(r));assertEquals(3,table(lib,"players").optJSONObject(0).optLong("revision"));}
 @Test public void customPlaceholderIsNotSavedAsAnotherSport(){JSONObject p=obj();put(p,"sport","Tennis");SportProfiles.select(p,"Custom");assertEquals("",p.optString("customSport"));put(p,"customSport","Goalball");SportProfiles.select(p,"Goalball");assertEquals(java.util.Arrays.asList("Goalball","Tennis"),SportProfiles.sports(p));assertFalse(SportProfiles.sports(p).contains("Custom"));SportProfiles.select(p,"tennis");assertEquals("Tennis",ProfileSetup.sport(p));}
}
